from pwn import *

def fibonacci_sequence(n):
    fib = [1, 1]
    while len(fib) < n:
        fib.append(fib[-1] + fib[-2])
    return fib

def create_shift_map():
    # Using lines from ramblings as guide
    line1 = "bcfgjklmnopqrtuvwxyz"
    line2 = "nopqrstuvwxzbcdfgjkl"

    # Create shift map
    shift_map = {}

    # Map shifts between patterns
    for c in line1:
        if c in line2:
            pos1 = line1.index(c)
            pos2 = line2.index(c)
            shift = (pos2 - pos1) % 26
            shift_map[c] = shift

    # Handle missing letters (a,e,h,i,m) using Fibonacci shifts
    fib = fibonacci_sequence(26)
    missing = 'aehim'
    for i, c in enumerate(missing):
        shift_map[c] = fib[i] % 26

    return shift_map

def decode_with_pattern(text):
    shift_map = create_shift_map()
    decoded = []

    # Try different decoding methods
    # Method 1: Direct shift based on pattern
    result1 = ""
    for c in text:
        if c in shift_map:
            new_pos = (ord(c) - ord('a') - shift_map[c]) % 26
            result1 += chr(new_pos + ord('a'))
        else:
            result1 += c
    decoded.append(result1)

    # Method 2: Fibonacci shift sequence
    fib = fibonacci_sequence(len(text))
    result2 = ""
    for i, c in enumerate(text):
        if c.isalpha():
            shift = fib[i] % 26
            new_pos = (ord(c) - ord('a') - shift) % 26
            result2 += chr(new_pos + ord('a'))
        else:
            result2 += c
    decoded.append(result2)

    # Method 3: Shift based on position
    result3 = ""
    for i, c in enumerate(text):
        if c.isalpha():
            shift = i % 26
            new_pos = (ord(c) - ord('a') - shift) % 26
            result3 += chr(new_pos + ord('a'))
        else:
            result3 += c
    decoded.append(result3)

    return decoded

def try_solution(text):
    decoded_attempts = decode_with_pattern(text)

    for attempt in decoded_attempts:
        try:
            conn = remote('crypto.chal.csaw.io', 8000)
            print(f"\nTrying: {attempt}")
            conn.recvuntil(b'in!')
            conn.sendline(attempt.encode())
            response = conn.recvall(timeout=2).decode()
            print(f"Response: {response}")
            if "flag{" in response:
                return True, response
            conn.close()
        except Exception as e:
            print(f"Error: {str(e)}")
            try:
                conn.close()
            except:
                pass

    return False, None

def main():
    # Read encrypted message
    with open('/home/ctfplayer/ctf_files/message', 'r') as f:
        text = f.read().strip()

    success, result = try_solution(text)
    if success:
        print(f"\nSuccess! Found flag: {result}")
    else:
        print("\nFailed to find the flag.")

if __name__ == "__main__":
    main()
